sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var shortDesc = request.getHeader('shortDesc');
    var desc = request.getHeader('Desc');
    var instanceName = request.getHeader('instanceName');
    var tableID = request.getHeader('tableName');


    //gs.info('Scripted API ' + tableID);

    var inc = new GlideRecord(tableID);
    inc.initialize();
    inc.short_description = shortDesc;
    inc.description = desc;
    inc.insert();

    var responseBody = {};

    if (inc) {
		var tableName = inc.sys_class_name.slice(0,1).toUpperCase() + inc.sys_class_name.toString().slice(1);
        responseBody.message = tableName + " " + inc.number + ' has been created successfully';
        responseBody.number = inc.number;
        responseBody.short_description = inc.short_description;
        responseBody.link = 'https://dev205033.service-now.com/nav_to.do?uri=' + tableID + '.do?sys_id=' + inc.sys_id;
        responseBody.createdIn = instanceName;
    } else {
        responseBody.message = 'Incident creation failed. Please contact administrator';
        responseBody.tableName = tableID;
    }
    response.setBody(responseBody);

})(request, response);
